A5568","text-anchor":"middle","font-size":13,"font-weight":400},"Québec"],["rect",{"x":304,"y":50.141999999999996,"width":72,"height":16,"fill":"#E8A825","rx":7},null],["text",{"x":340.0,"y":62.141999999999996,"fill":"#242628","text-anchor":"middle","font-size":11,"font-weight":700},"−12,18 M$"],["rect",{"x":470,"y":145.24,"width":79,"height":86.75999999999999,"fill":"#1A3560","rx":0},null],["text",{"x":509.5,"y":257,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"Canada"],["text",{"x":509.5,"y":137.24,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":600},"+14,46 M$"],["line",{"x1":209,"y1":72.142,"x2":300,"y2":72.142,"stroke":"#4A5568","stroke-width":1,"stroke-dasharray":"4 3"},null],["line",{"x1":379,"y1":145.24,"x2":470,"y2":145.24,"stroke":"#4A5568","stroke-width":1,"stroke-dasharray":"4 3"},null],["text",{"x":343,"y":281,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"Variation mensuelle des ventes"]].forEach(function(row){
