  svg.setAttribute(''font-family'',''system-ui, sans-serif'');
  [["rect",{"x":0,"y":0,"width":680,"height":300,"fill":"#FFFFFF","rx":0},null],["line",{"x1":66,"y1":232,"x2":623,"y2":232,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":236,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"0"],["line",{"x1":66,"y1":172,"x2":623,"y2":172,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":176,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"5"],["line",{"x1":66,"y1":112,"x2":623,"y2":112,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":116,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"10"],["line",{"x1":66,"y1":52,"x2":623,"y2":52,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":56,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"15"],["path",{"d":"M 116 52 L 269 112 L 422 172 L 575 232","fill":"none","stroke":"#1A3560","stroke-width":1.8},null],["circle",{"cx":116,"cy":52,"r":4.5,"fill":"#1A3560"},null],["text",{"x":116,"y":257,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"0"],["text",{"x":116,"y":42,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":600},"15"],["circle",{"cx":269,"cy":112,"r":4.5,"fill":"#1A3560"},null],["text",{"x":269,"y":257,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"5"],["text",{"x":269,"y":102,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":600},"10"],["circle",{"cx":422,"cy":172,"r":4.5,"fill":"#1A3560"},null],["text",{"x":422,"y":257,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"10"],["circle",{"cx":575,"cy":232,"r":4.5,"fill":"#1A3560"},null],["text",{"x":575,"y":257,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"15"],["text",{"x":575,"y":222,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":600},"0"