  [["rect",{"x":0,"y":0,"width":680,"height":300,"fill":"#FFFFFF","rx":0},null],["rect",{"x":240,"y":151,"width":192,"height":74,"fill":"#F0F6F0","rx":0},null],["line",{"x1":240,"y1":43,"x2":240,"y2":239,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":240,"y":259,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"9 h 30"],["line",{"x1":432,"y1":43,"x2":432,"y2":239,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":432,"y":259,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"13 h"],["line",{"x1":597,"y1":43,"x2":597,"y2":239,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":597,"y":259,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"16 h"],["text",{"x":222,"y":73,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"Jeudi · TSX"],["rect",{"x":240,"y":62,"width":357,"height":12,"fill":"#1A3560","rx":3},null],["text",{"x":222,"y":108,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"Jeudi · NYSE"],["text",{"x":253,"y":108,"fill":"#8A3030","text-anchor":"start","font-size":13,"font-weight":400},"Fermé"],["text",{"x":222,"y":174,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"Vendredi · TSX"],["rect",{"x":240,"y":163,"width":357,"height":12,"fill":"#1A3560","rx":3},null],["text",{"x":222,"y":208,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"Vendredi · NYSE"],["rect",{"x":240,"y":197,"width":192,"height":12,"fill":"#397955","rx":3},null],["rect",{"x":303,"y":215,"width":93,"height":16,"fill":"#E8A825","rx":7},null],["text",{"x":349.5,"y":227,"fill":"#242628","text-anchor":"middle","font-size":11,"font-weight":700},"3 h 30 ensemble"]].forEach(function(row){
